/**
 * Map an ISO 639-2/T or 639-2/B tag onto ISO 639-1. Already-2-letter tags pass through.
 *
 * @param tag Normalized lowercase language tag, optionally with a region/script suffix.
 */
export const iso6391FromTag = (tag: string): string => {
  const mapped = ISO_639_2_TO_1[tag]
  if (mapped) {
    return mapped
  }
  const base = tag.split('-')[0] ?? tag
  const baseMapped = ISO_639_2_TO_1[base]
  if (!baseMapped || baseMapped === base) {
    return tag
  }
  return `${baseMapped}${tag.slice(base.length)}`
}
